(332, 'Ops, o seu envio de mensagens foi bloqueado.', '=0D\r\n=0D\r\n  =0D\r\n    =0D\r\n    Email Locaweb=0D\r\n    =0D\r\n    =0D\r\n    =0D\r\n      .col-left{=0D\r\n        text-align: left;=0D\r\n      }=0D\r\n      .col-right{=0D\r\n        text-align: right;=0D\r\n      }=0D\r\n      @media screen and (max-width: 525px) {=0D\r\n        .he-wrapper {=0D\r\n          width: 100% !important;=0D\r\n          max-width: 100% !important;=0D\r\n        }=0D\r\n        .logo img {=0D\r\n          margin: 0 auto !important;=0D\r\n        }=0D\r\n        .mobile-hide {=0D\r\n          display: none !important;=0D\r\n        }=0D\r\n        .img-max {=0D\r\n          max-width: 100% !important;=0D\r\n          width: 100% !important;=0D\r\n          height: auto !important;=0D\r\n        }=0D\r\n        .responsive-table {=0D\r\n          width: 100% !important;=0D\r\n        }=0D\r\n        .padding {=0D\r\n          padding: 10px 5% 15px 5% !important;=0D\r\n        }=0D\r\n        .padding-meta {=0D\r\n          padding: 30px 5% 0px 5% !important;=0D\r\n          text-align: center;=0D\r\n        }=0D\r\n        .padding-copy {=0D\r\n          padding: 10px 5% 10px 5% !important;=0D\r\n          text-align: center;=0D\r\n        }=0D\r\n        .no-padding {=0D\r\n          padding: 0 !important;=0D\r\n        }=0D\r\n        .section-padding {=0D\r\n          padding: 50px 15px 50px 15px !important;=0D\r\n        }=0D\r\n        .mobile-button-container {=0D\r\n          margin: 0 auto;=0D\r\n          width: 100% !important;=0D\r\n        }=0D\r\n        .mobile-button {=0D\r\n          padding: 15px !important;=0D\r\n          border: 0 !important;=0D\r\n          font-size: 16px !important;=0D\r\n          display: block !important;=0D\r\n        }=0D\r\n        .he-col {=0D\r\n          min-width: 100% !important;=0D\r\n        }=0D\r\n        .col-left, .col-right{=0D\r\n          text-align: center !important;=0D\r\n        }=0D\r\n        .col-left table, .co